cd /output && node -e "
const fs = require('fs');
const content = fs.readFileSync('translation.md', 'utf8');
const braincode = content.match(/\`\`\`braincode\n([\s\S]*?)\n\`\`\`/)[1];

// Quick syntax check - count braces
const opens = (braincode.match(/{/g) || []).length;
const closes = (braincode.match(/}/g) || []).length;
console.log('Braces: opens=' + opens + ', closes=' + closes);

// Check for required elements
console.log('MODE TRACE:', braincode.includes('MODE TRACE'));
console.log('ENTRYPOINT:', braincode.includes('ENTRYPOINT Conversation'));
console.log('TURNs:', (braincode.match(/TURN t[0-9]/g) || []).length);
console.log('SOURCE locators:', (braincode.match(/SOURCE \"t[0-9]:s[0-9]/g) || []).length);
console.log('Syntax check: OK');
"
